INSERT INTO lessons (level_id,lesson_key,sort_order,title,title_translation,description,primary_outcome_key,estimated_duration_sec,source_hash,status,metadata)
VALUES (@level_id,'EN-A1-L-0045',45,'You read well','خوب می‌خوانی','با well هدف کوتاه این درس را تمرین کن.','EN-A1-OUTCOME-0045',420,'22aa9f5920a04db989b8fc1023cd06f52c8dccdcb39d2c7f429c647e0a4ac431','validated','{"outcomeFa":"well را در یک موقعیت کوتاه و طبیعی به کار ببری.","scenarioFa":"سارا برنامه را بلند می‌خواند و روبی می‌گوید او خوب می‌خواند.","prerequisiteOutcomeKeys":["EN-A1-OUTCOME-0044"],"curriculum":{"startingKnowledge":"early_a1_spoken_core_and_recent_review","targetConstructions":[{"key":"EN-CONSTR-0045-WELL","form":"You read well.","meaningFa":"گفتن این که کسی کاری را خوب انجام می‌دهد"}],"supportLanguage":[{"form":"You read this well.","meaningFa":"این را خوب می‌خوانی."},{"form":"And this?","meaningFa":"و این؟"}],"assessmentBoundary":"The Lesson introduces only the bounded A1 use of well shown here and does not claim broader sense mastery.","transferPlan":{"mode":"same_lesson","intent":"Recombine well in a second tightly controlled turn with familiar language."},"story":{"arcKey":"EN-A1-WALKING-GROUP","sceneKey":"EN-A1-FACTORY-SCENE-0045","learnerRoleKey":"sara","participants":["sara","ruby"],"introducedCharacterKeys":[],"relationshipState":"already_known","continuesLessonKey":"EN-A1-L-0039","dependsOnLessonKeys":["EN-A1-L-0039"],"settingFa":"مرکز محله، کنار تابلوی برنامه پیاده‌روی","storyBeatFa":"سارا برنامه را بلند می‌خواند و روبی می‌گوید او خوب می‌خواند."},"reviewLinks":[{"lessonKey":"EN-A1-L-0039","activityKeys":["A02"],"learningDemand":"retrieval","note":"Returning arc is spaced and learner role is deliberately rotated."}],"languageReference":{"specKey":"en-fa-A1-LESSON-SPEC-0045","specHash":"23eea3815e8c8dc70cfd8a7866d32db4d426dbdf620210984251a54ebcc5f6b3","grammarTargetKeys":[],"reviewLexicalLemmas":[],"usageFallbacks":[{"query":"read this well","rationale":"Exact target-collocation fallback for the character model turn."},{"query":"i read well","rationale":"Exact target-collocation fallback for the learner response."},{"query":"read this well too","rationale":"Exact target-collocation fallback for changed-context transfer."}],"noNewGrammarReason":"Lexical focus: the bounded adverb use of well is practiced without introducing a new grammar target."},"pedagogyVersion":2},"pilot":false,"audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange","qualityStage":"model_reviewed_for_testing","qualityV2Remediated":true,"qualityV2RemediationVersion":1}')
ON DUPLICATE KEY UPDATE level_id=VALUES(level_id),sort_order=VALUES(sort_order),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),primary_outcome_key=VALUES(primary_outcome_key),estimated_duration_sec=VALUES(estimated_duration_sec),source_hash=VALUES(source_hash),status=VALUES(status),metadata=VALUES(metadata);
